function verifpatient() {
    const idp = document.getElementById("idp").value;
    const f = document.getElementById("femme").checked;
    const h = document.getElementById("homme").checked;
    const np = document.getElementById("np").value;
    const tel = document.getElementById("tel").value;
    const ville = document.getElementById("ville").selectedIndex;
  
    if (idp.length != 4 || idp[0] != "p" || !numerique(idp.substr(1))) {
      alert(" veuiller verifier votre id");
      return false;
    }
    if (!h && !f) {
      alert("veuiller choisir le sexe ");
      return false;
    }
    if (np.length > 10 || !verifalpha(np)) {
      alert("veuiller verifier votre nom et prenom");
      return false;
    }
    if (tel.length != 8 || !numerique(tel)) {
      alert("verifier votre numero de telephone");
      return false;
    }
    if (ville == 0) {
      alert("veuiller choisir une ville");
      return false;
    }
  }
  
  function numerique(ch) {
    for (let i = 0; i < ch.length; i++) {
      if ("0" < ch[i] || ch[i] > "9") {
        return false;
      }
    }
    return true;
  }
  function verifalpha(ch) {
    ch = ch.toUpperCase();
    for (let i = 0; i < ch.length; i++) {
      if ("A" < ch[i] || (ch[i] > "Z" && ch[i] != " ")) {
        return false;
      }
    }
    return true;
  }

